def try_fix(s):
    if not s:
        return s, None
    candidates = []
    # Pattern 1: UTF-8 bytes shown as Latin-1 (mojibake with Ã, ¤, etc common for utf8->latin1)
    try:
        fixed = s.encode('latin1').decode('utf-8')
        candidates.append(('latin1->utf8', fixed))
    except Exception:
        pass
    # Pattern 2: Shift_JIS bytes shown as Latin-1
    try:
        fixed = s.encode('latin1').decode('shift_jis')
        candidates.append(('latin1->sjis', fixed))
    except Exception:
        pass
    # Pattern 3: EUC-JP bytes shown as latin1
    try:
        fixed = s.encode('latin1').decode('euc_jp')
        candidates.append(('latin1->eucjp', fixed))
    except Exception:
        pass
    # Pattern 4: cp1252 -> utf8
    try:
        fixed = s.encode('cp1252').decode('utf-8')
        candidates.append(('cp1252->utf8', fixed))
    except Exception:
        pass
    return candidates

