import json, re

with open('batches/batch_0065_fixed.json', encoding='utf-8') as f:
    data = json.load(f)

def fix_line(s, encs):
    for enc_from, enc_to in encs:
        try:
            return s.encode(enc_from).decode(enc_to)
        except Exception:
            pass
    return None

def score(s):
    if not s: return -1
    jp = len(re.findall(r'[぀-ヿ一-鿿]', s))
    bad = len(re.findall(r'[ÃÂ¤¥§¡ºµñ]', s))
    return jp - bad*2

encs_order = [('latin1','utf-8'), ('latin1','shift_jis'), ('latin1','euc_jp'), ('cp1252','utf-8')]

remaining_idx = [3252,3253,3258,3263,3271,3272,3280,3287,3294,3296]

for item in data:
    if item['idx'] not in remaining_idx:
        continue
    for field in ['title','body']:
        s = item.get(field,'')
        if not s or not re.search(r'[ÃÂ¤¥§¡ºµñ]', s):
            continue
        lines = s.split('\n')
        new_lines = []
        for line in lines:
            if not re.search(r'[ÃÂ¤¥§¡ºµñ]', line):
                new_lines.append(line)
                continue
            best_line = line
            best_score = score(line)
            for enc_from, enc_to in encs_order:
                try:
                    cand = line.encode(enc_from).decode(enc_to)
                    if score(cand) > best_score:
                        best_line = cand
                        best_score = score(cand)
                except Exception:
                    continue
            new_lines.append(best_line)
        item[field] = '\n'.join(new_lines)

with open('batches/batch_0065_fixed.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=1)

for item in data:
    if item['idx'] in remaining_idx:
        print(item['idx'], item['name'])
        print(' title:', item['title'][:100])
        print(' body[:200]:', item['body'][:200])
        print()
